import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs';
import { AuthService } from '../../core/services/auth.service';
import { ApiService } from '../../core/services/api.service';
import { ChatWidgetComponent } from '../chat-widget/chat-widget.component';

@Component({
  selector: 'app-layout',
  standalone: true,
  imports: [CommonModule, RouterModule, ChatWidgetComponent],
  template: `
    <div class="app-shell">

      <!-- ── Sidebar ───────────────────────────────────────── -->
      <aside class="sidebar">
        <div class="sidebar-logo">
          <div class="logo-icon">⬡</div>
          <div>
            <div class="logo-name">DevSecOps</div>
            <div class="logo-sub">AI Platform · Vermeg</div>
          </div>
        </div>

        <nav class="sidebar-nav">
          <div class="nav-section">Principal</div>
          <a class="nav-item" routerLink="/dashboard" routerLinkActive="active">
            <span class="nav-icon">◈</span> Dashboard
          </a>
          <a class="nav-item" routerLink="/projects" routerLinkActive="active">
            <span class="nav-icon">◧</span> Projets
          </a>
          <a class="nav-item" routerLink="/incidents" routerLinkActive="active">
            <span class="nav-icon">⬡</span> Incidents
            <span class="nav-badge" *ngIf="openCount > 0">{{openCount}}</span>
          </a>

          <div class="nav-section" style="margin-top:16px;">Agents IA</div>
          <a class="nav-item" routerLink="/analysis" routerLinkActive="active">
            <span class="nav-icon">◆</span> Analyses
          </a>

          <div class="nav-section" style="margin-top:16px;">Système</div>
          <a class="nav-item" routerLink="/notifications" routerLinkActive="active">
            <span class="nav-icon">◉</span> Notifications
            <span class="nav-badge warn" *ngIf="notifCount > 0">{{notifCount}}</span>
          </a>
          <a class="nav-item" routerLink="/settings" routerLinkActive="active">
            <span class="nav-icon">◎</span> Paramètres
          </a>
          <a class="nav-item" routerLink="/admin" routerLinkActive="active" *ngIf="isAdmin">
            <span class="nav-icon">▣</span> Admin
          </a>
        </nav>

        <div class="sidebar-footer">
          <div class="user-info">
            <div class="user-avatar">{{userInitials}}</div>
            <div>
              <div class="user-name">{{currentUser?.username}}</div>
              <div class="user-role">{{currentUser?.role}}</div>
            </div>
          </div>
          <button class="logout-btn" (click)="logout()" title="Déconnexion">⏻</button>
        </div>
      </aside>

      <!-- ── Main ──────────────────────────────────────────── -->
      <div class="main-content">
        <header class="topbar">
          <span class="topbar-title">{{pageTitle}}</span>
          <div class="live-indicator">
            <div class="live-dot"></div> Temps réel
          </div>
        </header>
        <router-outlet></router-outlet>
      </div>

    </div>

    <!-- ── Chat Widget ───────────────────────────────────── -->
    <app-chat-widget></app-chat-widget>
  `,
  styles: [`
    .sidebar {
      position: fixed;
      top: 0; left: 0; bottom: 0;
      width: var(--sidebar-width);
      background: var(--bg-secondary);
      border-right: 1px solid var(--border);
      display: flex;
      flex-direction: column;
      z-index: 100;
    }

    .sidebar-logo {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 18px 16px;
      border-bottom: 1px solid var(--border);
    }

    .logo-icon {
      font-size: 20px;
      color: var(--accent-blue);
    }

    .logo-name {
      font-size: 13px;
      font-weight: 700;
      color: var(--accent-blue);
      letter-spacing: 2px;
      text-transform: uppercase;
      font-family: var(--font-mono);
    }

    .logo-sub {
      font-size: 9px;
      color: var(--text-faint);
      letter-spacing: 0.5px;
    }

    .sidebar-nav {
      flex: 1;
      padding: 12px 8px;
      overflow-y: auto;
    }

    .nav-section {
      font-size: 9px;
      color: var(--text-faint);
      letter-spacing: 2px;
      text-transform: uppercase;
      padding: 4px 10px;
      margin-bottom: 4px;
      font-family: var(--font-mono);
    }

    .nav-item {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 10px;
      border-radius: var(--radius-md);
      font-size: 12px;
      color: var(--text-muted);
      cursor: pointer;
      margin-bottom: 2px;
      transition: all 0.15s;
      text-decoration: none;
      font-family: var(--font-sans);

      &:hover { background: var(--bg-hover); color: var(--text-secondary); text-decoration: none; }
      &.active {
        background: var(--bg-hover);
        color: var(--accent-blue);
        border-left: 2px solid var(--accent-blue);
        padding-left: 8px;
      }
    }

    .nav-icon { font-size: 13px; width: 16px; text-align: center; flex-shrink: 0; }

    .nav-badge {
      margin-left: auto;
      background: var(--accent-red-bg);
      color: var(--accent-red);
      font-size: 9px;
      font-weight: 700;
      padding: 2px 6px;
      border-radius: 10px;
      font-family: var(--font-mono);

      &.warn { background: var(--accent-orange-bg); color: var(--accent-orange); }
    }

    .sidebar-footer {
      padding: 12px 16px;
      border-top: 1px solid var(--border);
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .user-info {
      display: flex;
      align-items: center;
      gap: 8px;
      flex: 1;
      min-width: 0;
    }

    .user-avatar {
      width: 30px; height: 30px;
      border-radius: 50%;
      background: var(--accent-blue-bg);
      border: 1px solid var(--accent-blue);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 700;
      color: var(--accent-blue);
      flex-shrink: 0;
      font-family: var(--font-mono);
    }

    .user-name {
      font-size: 12px;
      color: var(--text-secondary);
      font-weight: 500;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .user-role {
      font-size: 10px;
      color: var(--text-faint);
      font-family: var(--font-mono);
    }

    .logout-btn {
      background: transparent;
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      color: var(--text-muted);
      padding: 6px 8px;
      cursor: pointer;
      font-size: 14px;
      transition: all 0.15s;

      &:hover { border-color: var(--accent-red); color: var(--accent-red); background: var(--accent-red-bg); }
    }
  `]
})
export class LayoutComponent implements OnInit {
  openCount  = 0;
  notifCount = 0;
  pageTitle  = 'Dashboard';

  private pageTitles: Record<string, string> = {
    '/dashboard':     'Vue d\'ensemble',
    '/projects':      'Projets',
    '/incidents':     'Incidents',
    '/analysis':      'Analyses IA',
    '/notifications': 'Notifications',
    '/settings':      'Paramètres',
    '/admin':         'Administration'
  };

  constructor(
    private auth: AuthService,
    private api: ApiService,
    private router: Router
  ) {}

  ngOnInit() {
    this.loadCounts();
    this.router.events
      .pipe(filter(e => e instanceof NavigationEnd))
      .subscribe((e: any) => {
        const path = '/' + e.urlAfterRedirects.split('/')[1];
        this.pageTitle = this.pageTitles[path] || 'DevSecOps IA';
      });
    const path = '/' + this.router.url.split('/')[1];
    this.pageTitle = this.pageTitles[path] || 'DevSecOps IA';
  }

  loadCounts() {
    this.api.getIncidents({ status: 'OPEN', size: 1 }).subscribe((r: any) => {
      this.openCount = r.totalElements || r.length || 0;
    });
    this.api.getNotifications().subscribe((n: any[]) => {
      this.notifCount = n.filter(x => !x.read).length;
    });
  }

  logout() { this.auth.logout(); }

  get currentUser() { return this.auth.currentUser; }
  get isAdmin()     { return this.auth.isAdmin; }
  get userInitials() {
    const u = this.auth.currentUser;
    if (!u) return 'U';
    return (u.username || u.email || 'U').substring(0, 2).toUpperCase();
  }
}
